  loanCompletedChip: { en: "Completed", bn: "সম্পন্ন" },
  loanLoansSuffix: { en: "loans", bn: "ঋণ" },
  loanZeroInterestShort: { en: "0% interest", bn: "০% সুদ" },
  loanTermsTitle: { en: "Qard Hasan Terms & Conditions", bn: "কারদ-হাসান শর্তাবলী" },
  loanTerm1Title: { en: "1. Sharia Compliance", bn: "১. শরিয়াহ্‌ সম্মতি" },
  loanTerm1: { en: "This is a Qard Hasan (benevolent loan) — completely interest-free (riba-free). The borrower repays only the principal amount plus a one-time flat service fee.", bn: "এটি একটি কারদ-হাসান (কল্যাণমূলক ঋণ) — সম্পূর্ণ সুদমুক্ত (রিবা-মুক্ত)। ঋণগ্রহীতা শুধু মূল পরিমাণ এবং একবার ফ্ল্যাট সেবা ফি পরিশোধ করেন।" },
  loanTerm2Title: { en: "2. Service Fee", bn: "২. সেবা ফি" },
  loanTerm2Prefix: { en: "A flat", bn: "একটি ফ্ল্যাট" },
  loanTerm2Suffix: { en: "one-time service fee is charged to cover administrative and operational costs. This fee does not compound or increase over time.", bn: "একবার সেবা ফি প্রশাসনিক ও পরিচালনা খরচ মেটাতে নেওয়া হয়। এই ফি চক্রবৃদ্ধি বা সময়ের সাথে বাড়ে না।" },
  loanTerm3Title: { en: "3. Repayment", bn: "৩. পরিশোধ" },
  loanTerm3: { en: "Equal monthly installments auto-deducted from your wallet. Maintain sufficient balance. 3 consecutive misses may result in account restrictions.", bn: "সমান মাসিক কিস্তি ওয়ালেট থেকে স্বয়ংক্রিয়ভাবে কেটে নেওয়া হয়। পর্যাপ্ত ব্যালেন্স রাখুন। পরপর ৩বার মিস হলে অ্যাকাউন্টে বিধিনিষেধ আসতে পারে।" },
  loanTerm4Title: { en: "4. No Penalty Interest", bn: "৪. কোনো জরিমানা সুদ নেই" },
  loanTerm4: { en: "Late payments do not accrue additional interest or riba. However, repeated defaults may affect your Trust Score and future eligibility.", bn: "বিলম্বিত পরিশোধে অতিরিক্ত সুদ বা রিবা যোগ হয় না। তবে বারবার খেলাপি হলে আপনার ট্রাস্ট স্কোর ও ভবিষ্যৎ যোগ্যতায় প্রভাব পড়তে পারে।" },
  loanTerm5Title: { en: "5. Eligibility", bn: "৫. যোগ্যতা" },
  loanTerm5: { en: "Approval depends on Trust Score, transaction history, and KYC verification. EasyPay reserves the right to decline applications.", bn: "অনুমোদন ট্রাস্ট স্কোর, লেনদেন ইতিহাস ও কেওয়াইসি যাচাইয়ের উপর নির্ভর করে। ইজিপে আবেদন প্রত্যাখ্যানের অধিকার রাখে।" },
  loanTerm6Title: { en: "6. Early Settlement", bn: "৬. আগাম পরিশোধ" },
  loanTerm6: { en: "Full early repayment is allowed at any time without penalty. Service fee remains unchanged regardless of early settlement.", bn: "যেকোনো সময় জরিমানা ছাড়াই সম্পূর্ণ আগাম পরিশোধ করা যাবে। আগাম পরিশোধ হলেও সেবা ফি অপরিবর্তিত থাকে।" },
  loanTerm7Title: { en: "7. Default & Recovery", bn: "৭. খেলাপি ও আদায়" },
  loanTerm7: { en: "On default: account restrictions, deductions from incoming funds, and Trust Score reduction. No additional interest or charges are levied.", bn: "খেলাপি হলে: অ্যাকাউন্টে বিধিনিষেধ, আগত অর্থ থেকে কর্তন এবং ট্রাস্ট স্কোর হ্রাস। কোনো অতিরিক্ত সুদ বা চার্জ নেওয়া হয় না।" },
  loanTerm8Title: { en: "8. Data Privacy", bn: "৮. ডেটা গোপনীয়তা" },
  loanTerm8: { en: "Transaction data is used solely for Trust Score calculation. No third-party sharing except as required by law.", bn: "লেনদেন তথ্য শুধু ট্রাস্ট স্কোর গণনার জন্য ব্যবহার হয়। আইন অনুযায়ী ছাড়া তৃতীয় পক্ষের সাথে শেয়ার করা হয় না।" },
  loanTerm9Title: { en: "9. Governing Principle", bn: "৯. পরিচালনা নীতি" },
  loanTerm9: { en: "This agreement follows Islamic finance principles (Qard Hasan). Governed by laws of the People's Republic of Bangladesh.", bn: "এই চুক্তি ইসলামিক ফিন্যান্স নীতি (কারদ-হাসান) অনুসরণ করে। গণপ্রজাতন্ত্রী বাংলাদেশের আইন দ্বারা পরিচালিত।" },
  loanAgreeTermsPrefix: { en: "I agree to the", bn: "আমি" },
  loanAgreeTermsMiddle: { en: "Qard Hasan Terms", bn: "কারদ-হাসান শর্তাবলী" },
  loanAgreeTermsSuffix: { en: "including the service fee and repayment policies. I understand this loan is interest-free.", bn: "এবং সেবা ফি ও পরিশোধ নীতি মেনে নিচ্ছি। আমি বুঝতে পারছি এই ঋণ সুদমুক্ত।" },
