  agdFaq1A: { en: "Tap 'Float Req' from Quick Actions and enter the amount. Your distributor will be notified.", bn: "কুইক অ্যাকশন থেকে 'ফ্লোট রিক' ট্যাপ করে পরিমাণ দিন। আপনার ডিস্ট্রিবিউটরকে জানানো হবে।" },
  agdFaq2Q: { en: "Cash In transaction failed?", bn: "ক্যাশ ইন লেনদেন ব্যর্থ?" },
  agdFaq2A: { en: "Check your balance and retry. If the issue persists, contact your distributor with the transaction ID.", bn: "আপনার ব্যালেন্স দেখে আবার চেষ্টা করুন। সমস্যা থাকলে লেনদেন আইডি সহ ডিস্ট্রিবিউটরকে জানান।" },
