  agdFaq3A: { en: "You earn 0.49% on Cash In/Out and 0.019% on Bill Pay transactions, credited instantly.", bn: "আপনি ক্যাশ ইন/আউটে ০.৪৯% এবং বিল পে-তে ০.০১৯% কমিশন পান, যা তাৎক্ষণিক জমা হয়।" },
  agdFaq4Q: { en: "How to register a new customer?", bn: "নতুন গ্রাহক কীভাবে রেজিস্টার করব?" },
  agdFaq4A: { en: "Tap 'Register' and fill in the customer's phone, name, and NID details.", bn: "'রেজিস্টার' ট্যাপ করে গ্রাহকের ফোন, নাম ও এনআইডি বিবরণ পূরণ করুন।" },
