  rlpTaglineSD: { en: "Sign in with your super-distributor account.", bn: "আপনার সুপার-ডিস্ট্রিবিউটর অ্যাকাউন্ট দিয়ে সাইন ইন করুন।" },
  rlpDescAdmin: { en: "EasyPay Admin – manage users, transactions, fraud alerts and platform settings.", bn: "ইজিপে অ্যাডমিন – ব্যবহারকারী, লেনদেন, জালিয়াতির সতর্কতা ও প্ল্যাটফর্ম সেটিংস পরিচালনা করুন।" },
  rlpDescAgent: { en: "EasyPay Agent – cash-in, cash-out, bill pay and customer onboarding.", bn: "ইজিপে এজেন্ট – ক্যাশ-ইন, ক্যাশ-আউট, বিল পরিশোধ ও গ্রাহক নিবন্ধন।" },
  rlpDescMerchant: { en: "EasyPay Merchant – accept payments, manage products and track analytics.", bn: "ইজিপে মার্চেন্ট – পেমেন্ট গ্রহণ, পণ্য পরিচালনা ও অ্যানালিটিক্স ট্র্যাক করুন।" },
  rlpDescDistributor: { en: "EasyPay Distributor – create agents, manage float and track commissions.", bn: "ইজিপে ডিস্ট্রিবিউটর – এজেন্ট তৈরি, ফ্লোট পরিচালনা ও কমিশন ট্র্যাক করুন।" },
  rlpDescSD: { en: "EasyPay Super Distributor – manage distributors, float and commission networks.", bn: "ইজিপে সুপার ডিস্ট্রিবিউটর – ডিস্ট্রিবিউটর, ফ্লোট ও কমিশন নেটওয়ার্ক পরিচালনা করুন।" },

