export type TranslationKey = keyof typeof translations;
export const translationsMap = translations;

/** Dev-only registry of keys requested but missing in current language. */
const missingKeys = new Set<string>();
const warnedKeys = new Set<string>();
/** key::lang -> Set of source file references (e.g. "src/pages/AccountPage.tsx:123") */
const missingSources = new Map<string, Set<string>>();
type Listener = () => void;
const listeners = new Set<Listener>();

export interface MissingTranslationEntry {
  key: string;
  lang: Lang;
  sources: string[];
}

let cachedSnapshot: MissingTranslationEntry[] = [];
function rebuildSnapshot() {
  cachedSnapshot = Array.from(missingKeys).map((id) => {
    const [key, lang] = id.split("::") as [string, Lang];
    return { key, lang, sources: Array.from(missingSources.get(id) ?? []) };
  });
}

export function getMissingTranslationKeys(): string[] {
  return Array.from(missingKeys);
}

export function getMissingTranslations(): MissingTranslationEntry[] {
  return cachedSnapshot;
}

export function subscribeMissingTranslations(fn: Listener): () => void {
  listeners.add(fn);
  return () => {
    listeners.delete(fn);
  };
}

function notifyMissing() {
  rebuildSnapshot();
  listeners.forEach((l) => l());
}

export function resetMissingTranslationKeys(): void {
  missingKeys.clear();
  warnedKeys.clear();
  missingSources.clear();
  notifyMissing();
}


/** Parse a stack trace and return the first frame inside src/ that isn't i18n.tsx itself. */
function inferCallerSource(): string | null {
  try {
    const stack = new Error().stack;
    if (!stack) return null;
    for (const line of stack.split("\n")) {
      const m = line.match(/\/src\/([^)\s:]+\.(?:tsx?|jsx?)):(\d+):\d+/);
      if (!m) continue;
      if (m[1].endsWith("lib/i18n.tsx")) continue;
      return `src/${m[1]}:${m[2]}`;
    }
  } catch {
    /* ignore */
  }
  return null;
}

interface I18nContextValue {
  lang: Lang;
  toggleLang: () => void;
  t: (key: TranslationKey) => string;
}

const I18nContext = createContext<I18nContextValue | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>(() => (localStorage.getItem(LANG_KEY) as Lang) ?? "en");
  // Track which user's preference we've hydrated so we don't overwrite mid-toggle.
  const hydratedForUserRef = (globalThis as any).__i18nHydratedRef ||= { current: null as string | null };

  useEffect(() => {
    localStorage.setItem(LANG_KEY, lang);
    // Sync <html lang> so Bangla-optimized CSS (font, line-height, size) activates.
    if (typeof document !== "undefined") {
      document.documentElement.setAttribute("lang", lang);
    }
  }, [lang]);

  // Hydrate from profile on sign-in; persist changes back to profile.
  useEffect(() => {
    let cancelled = false;
    // Lazy import to avoid circular deps at module init.
    import("@/integrations/supabase/client").then(({ supabase }) => {
      const applyForUser = async (userId: string | null) => {
        if (!userId) {
          hydratedForUserRef.current = null;
          return;
        }
        if (hydratedForUserRef.current === userId) return;
        const { data } = await supabase
          .from("profiles")
          .select("lang_pref")
          .eq("user_id", userId)
          .maybeSingle();
        if (cancelled) return;
        hydratedForUserRef.current = userId;
        const remote = (data?.lang_pref as Lang | undefined) ?? null;
        if (remote === "en" || remote === "bn") {
          setLangState(remote);
          localStorage.setItem(LANG_KEY, remote);
        }
      };

      supabase.auth.getSession().then(({ data }) => {
        applyForUser(data.session?.user?.id ?? null);
      });
      const { data: sub } = supabase.auth.onAuthStateChange((_evt, session) => {
        applyForUser(session?.user?.id ?? null);
      });
      (globalThis as any).__i18nAuthSub = sub;
    });
    return () => {
      cancelled = true;
      const sub = (globalThis as any).__i18nAuthSub;
      sub?.subscription?.unsubscribe?.();
    };
  }, []);

  const setLang = useCallback((next: Lang) => {
    setLangState(next);
    // Fire-and-forget persist to profile if signed in.
    import("@/integrations/supabase/client").then(({ supabase }) => {
      supabase.auth.getSession().then(({ data }) => {
        const uid = data.session?.user?.id;
        if (!uid) return;
        supabase.from("profiles").update({ lang_pref: next }).eq("user_id", uid).then(() => {});
      });
    });
  }, []);

  const toggleLang = useCallback(() => {
    setLang(lang === "en" ? "bn" : "en");
  }, [lang, setLang]);


  const t = useCallback(
    (key: TranslationKey) => {
      const entry = (translations as Record<string, { en: string; bn: string } | undefined>)[key as string];
      const value = entry?.[lang];
      if (!value) {
        const id = `${String(key)}::${lang}`;
        const isNew = !missingKeys.has(id);
        missingKeys.add(id);
        if (import.meta.env.DEV) {
          const src = inferCallerSource();
          if (src) {
            let set = missingSources.get(id);
            if (!set) {
              set = new Set();
              missingSources.set(id, set);
            }
            set.add(src);
          }
          if (!warnedKeys.has(id)) {
            warnedKeys.add(id);
            // eslint-disable-next-line no-console
            console.warn(
              `[i18n] Missing translation for "${String(key)}" (lang=${lang})${src ? ` at ${src}` : ""}`
            );
          }
          if (isNew) {
            // Defer to avoid render-phase setState in subscribers.
            queueMicrotask(notifyMissing);
          }
        }
        // Visible fallback so QA can spot gaps in the UI
        return `⟦${String(key)}⟧`;
      }
      return value;
    },
    [lang]
  );

  return (
    <I18nContext.Provider value={{ lang, toggleLang, t }}>
      {children}
    </I18nContext.Provider>
  );
}

export function useI18n() {
  const ctx = useContext(I18nContext);
  if (!ctx) throw new Error("useI18n must be used inside I18nProvider");
  return ctx;
}

export function useOptionalI18n() {
  return useContext(I18nContext);
}
